  7	import java.math.BigDecimal;
  8	import java.time.LocalDate;
  9	import java.time.format.DateTimeFormatter;
 10	import java.util.List;
 11	import java.util.Optional;
 12	
 13	public class ReservationService {
 14	    private final ReservationRepository reservationRepo;
 15	    private final RoomRepository roomRepo;
 16	    private final MessageRepository messageRepo;
 17	    private final PricingService pricingService;
 18	
 19	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
 20	    private static final DateTimeFormatter CSV_DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
 21	    private static final String CURRENCY_FORMAT = "R$ %.2f";
 22	
 23	    public ReservationService(
 24	        ReservationRepository reservationRepo,
 25	        RoomRepository roomRepo,
 26	        MessageRepository messageRepo,
 27	        PricingService pricingService
 28	    ) {
 29	        this.reservationRepo = reservationRepo;
 30	        this.roomRepo = roomRepo;
 31	        this.messageRepo = messageRepo;
 32	        this.pricingService = pricingService;
 33	    }
 34	
 35	    public Reservation createReservation(
 36	        int roomNumber,
 37	        String guestName,
 38	        String guestEmail,
 39	        String guestCpf,
 40	        LocalDate checkIn,
 41	        LocalDate checkOut,
 42	        int guests,
 43	        RatePlan ratePlan
 44	    ) {
 45	        Room room = roomRepo.findByNumber(roomNumber)
 46	            .orElseThrow(() -> new IllegalArgumentException("ROOM_NOT_FOUND"));
 47	
 48	        if (guests < 1 || guests > room.capacity()) {
 49	            throw new IllegalArgumentException(guests < 1 ? "INVALID_REQUEST" : "CAPACITY_EXCEEDED");
 50	        }
 51	
 52	        if (!checkOut.isAfter(checkIn)) {
 53	            throw new IllegalArgumentException("INVALID_REQUEST");
 54	        }
 55	
 56	        if (isRoomUnavailable(roomNumber, checkIn, checkOut)) {
 57	            throw new IllegalArgumentException("ROOM_UNAVAILABLE");
 58	        }
 59	
 60	        int nights = pricingService.countNights(checkIn, checkOut);
 61	        BigDecimal subtotal = pricingService.calculateSubtotal(room.nightly(), checkIn, checkOut);
 62	        BigDecimal discount = pricingService.calculateDiscount(
 63	            subtotal,
 64	            ratePlan == RatePlan.NON_REFUNDABLE
 65	        );
 66	        BigDecimal total = pricingService.calculateTotal(subtotal, discount);
 67	
 68	        long id = reservationRepo.getNextId();
 69	        Reservation reservation = new Reservation(
 70	            id,
 71	            roomNumber,
 72	            guestName,
 73	            guestEmail,
 74	            guestCpf,
 75	            checkIn,
 76	            checkOut,
 77	            guests,
 78	            ratePlan,
 79	            nights,
 80	            subtotal,
 81	            discount,
 82	            total
 83	        );
 84	
 85	        return reservationRepo.save(reservation);
 86	    }
 87	
 88	    public Reservation confirmReservation(long reservationId) {
 89	        Reservation reservation = reservationRepo.findById(reservationId)
 90	            .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
 91	
 92	        if (reservation.getStatus() != ReservationStatus.PENDING) {
 93	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
 94	        }
 95	
 96	        reservation.confirm(reservation.getTotal());
 97	
 98	        Room room = roomRepo.findByNumber(reservation.getRoomNumber()).orElseThrow();
 99	
100	        sendGuestConfirmationEmail(reservation, room);
101	        sendGovernanceConfirmationEmail(reservation, room);
102	        sendFinanceConfirmationEmail(reservation);
103	
104	        return reservationRepo.save(reservation);
105	    }
106	
107	    public Reservation cancelReservation(long reservationId) {
108	        Reservation reservation = reservationRepo.findById(reservationId)
109	            .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
110	
111	        if (reservation.getStatus() == ReservationStatus.CHECKED_IN ||
112	            reservation.getStatus() == ReservationStatus.CHECKED_OUT ||
113	            reservation.getStatus() == ReservationStatus.CANCELLED) {
114	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
115	        }
116	
117	        BigDecimal refund = BigDecimal.ZERO;
118	        if (reservation.getStatus() == ReservationStatus.CONFIRMED) {
119	            if (reservation.getRatePlan() == RatePlan.STANDARD) {
120	                refund = reservation.getAmountPaid();
121	            }
122	        }
123	
124	        reservation.cancel(refund);
125	
126	        if (reservation.getStatus() == ReservationStatus.CONFIRMED) {
127	            Room room = roomRepo.findByNumber(reservation.getRoomNumber()).orElseThrow();
128	            sendGovernanceCancellationEmail(reservation, room);
129	            if (refund.compareTo(BigDecimal.ZERO) > 0) {
130	                sendFinanceCancellationEmail(reservation);
131	            }
132	        }
133	
134	        return reservationRepo.save(reservation);
135	    }
136	
137	    public Reservation checkIn(long reservationId) {
138	        Reservation reservation = reservationRepo.findById(reservationId)
139	            .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
140	
141	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
142	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
143	        }
144	
145	        reservation.checkIn();
146	        return reservationRepo.save(reservation);
147	    }
148	
149	    public Reservation checkOut(long reservationId) {
150	        Reservation reservation = reservationRepo.findById(reservationId)
151	            .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
152	
153	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
154	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
155	        }
156	
157	        reservation.checkOut();
158	        return reservationRepo.save(reservation);
159	    }
160	
161	    public Reservation getReservation(long reservationId) {
162	        return reservationRepo.findById(reservationId)
163	            .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
164	    }
165	
166	    public ReservationDocument getReservationDocument(long reservationId) {
167	        Reservation reservation = reservationRepo.findById(reservationId)
168	            .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
169	
170	        if (reservation.getAmountPaid().compareTo(BigDecimal.ZERO) == 0) {
171	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
172	        }
173	
174	        Room room = roomRepo.findByNumber(reservation.getRoomNumber()).orElseThrow();
175	        return new ReservationDocument(
176	            "Comprovante de reserva",
177	            reservation.getId(),
178	            reservation.getGuestName(),
179	            reservation.getGuestCpf(),
180	            reservation.getRoomNumber(),
181	            room.type().displayName,
182	            reservation.getCheckIn(),
183	            reservation.getCheckOut(),
184	            reservation.getNights(),
185	            reservation.getSubtotal(),
186	            reservation.getDiscount(),
187	            reservation.getTotal()
188	        );
189	    }
190	
191	    private boolean isRoomUnavailable(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
192	        return reservationRepo.findAll().stream()
193	            .filter(r -> r.getRoomNumber() == roomNumber)
194	            .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
195	            .anyMatch(r -> hasOverlap(r.getCheckIn(), r.getCheckOut(), checkIn, checkOut));
196	    }
197	
198	    private boolean hasOverlap(LocalDate start1, LocalDate end1, LocalDate start2, LocalDate end2) {
199	        return start1.isBefore(end2) && start2.isBefore(end1);
200	    }
