202	    private void sendGuestConfirmationEmail(Reservation reservation, Room room) {
203	        String body = buildGuestConfirmationBody(reservation, room);
204	        Message message = new Message(
205	            messageRepo.getNextId(),
206	            MessageChannel.EMAIL,
207	            reservation.getGuestEmail(),
208	            "Reserva confirmada - Pousada Maré Alta",
209	            body
210	        );
211	        messageRepo.save(message);
212	    }
