214	    private void sendGovernanceConfirmationEmail(Reservation reservation, Room room) {
215	        String dates = formatDateRange(reservation.getCheckIn(), reservation.getCheckOut());
216	        String subject = String.format("Reserva confirmada - quarto %d", reservation.getRoomNumber());
217	        String body = String.format(
218	            "Entrada: %s | Saída: %s\nHóspedes: %d",
219	            reservation.getCheckIn().format(DATE_FORMATTER),
220	            reservation.getCheckOut().format(DATE_FORMATTER),
221	            reservation.getGuests()
222	        );
223	        Message message = new Message(
224	            messageRepo.getNextId(),
225	            MessageChannel.EMAIL,
226	            "governanca@pousadamarealta.com.br",
227	            subject,
228	            body
229	        );
230	        messageRepo.save(message);
231	    }
232	
233	    private void sendFinanceConfirmationEmail(Reservation reservation) {
234	        String subject = String.format("Pagamento recebido - reserva %d", reservation.getId());
235	        String body = String.format("Valor pago: %s", formatCurrency(reservation.getAmountPaid()));
236	        Message message = new Message(
237	            messageRepo.getNextId(),
238	            MessageChannel.EMAIL,
239	            "financeiro@pousadamarealta.com.br",
240	            subject,
241	            body
242	        );
243	        messageRepo.save(message);
244	    }
245	
246	    private void sendGovernanceCancellationEmail(Reservation reservation, Room room) {
247	        String subject = String.format("Reserva cancelada - quarto %d", reservation.getRoomNumber());
248	        String body = String.format(
249	            "Datas liberadas: %s a %s",
250	            reservation.getCheckIn().format(DATE_FORMATTER),
251	            reservation.getCheckOut().format(DATE_FORMATTER)
252	        );
253	        Message message = new Message(
254	            messageRepo.getNextId(),
