259	        );
260	        messageRepo.save(message);
261	    }
262	
263	    private void sendFinanceCancellationEmail(Reservation reservation) {
264	        String subject = String.format("Reembolso - reserva %d", reservation.getId());
265	        String body = String.format("Valor a devolver: %s", formatCurrency(reservation.getRefund()));
266	        Message message = new Message(
267	            messageRepo.getNextId(),
268	            MessageChannel.EMAIL,
269	            "financeiro@pousadamarealta.com.br",
