271	            body
272	        );
273	        messageRepo.save(message);
274	    }
275	
276	    private String buildGuestConfirmationBody(Reservation reservation, Room room) {
277	        StringBuilder sb = new StringBuilder();
278	        sb.append("Olá, ").append(reservation.getGuestName()).append("!\n\n");
279	        sb.append("Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n");
280	        sb.append(buildComprovante(reservation, room));
281	        sb.append("\n\nA entrada é a partir das 14h, e a saída, até as 12h.\n");
282	        sb.append("Até breve!");
283	        return sb.toString();
284	    }
285	
286	    private String buildComprovante(Reservation reservation, Room room) {
287	        StringBuilder sb = new StringBuilder();
288	        sb.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
289	        sb.append("Hóspede: ").append(reservation.getGuestName())
290	            .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
291	        sb.append("Quarto: ").append(reservation.getRoomNumber())
292	            .append(" (").append(room.type().displayName).append(")\n");
293	        sb.append("Entrada: ").append(reservation.getCheckIn().format(DATE_FORMATTER))
294	            .append(" | Saída: ").append(reservation.getCheckOut().format(DATE_FORMATTER))
295	            .append(" | ").append(reservation.getNights()).append(" diária");
296	        if (reservation.getNights() > 1) sb.append("s");
297	        sb.append("\n");
298	        sb.append("Diárias: ").append(formatCurrency(reservation.getSubtotal())).append("\n");
299	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
300	            sb.append("Desconto: ").append(formatCurrency(reservation.getDiscount())).append("\n");
301	        }
302	        sb.append("Total: ").append(formatCurrency(reservation.getTotal()));
303	        return sb.toString();
304	    }
305	
306	    private String formatCurrency(BigDecimal value) {
307	        return String.format("R$ %.2f", value);
308	    }
309	
310	    private String formatCpf(String cpf) {
311	        if (cpf.length() != 11) return cpf;
312	        return String.format("%s.%s.%s-%s",
313	            cpf.substring(0, 3),
314	            cpf.substring(3, 6),
315	            cpf.substring(6, 9),
316	            cpf.substring(9, 11)
317	        );
318	    }
319	
320	    private String formatDateRange(LocalDate checkIn, LocalDate checkOut) {
321	        return String.format("%s a %s",
322	            checkIn.format(DATE_FORMATTER),
323	            checkOut.format(DATE_FORMATTER)
324	        );
325	    }
326	}
