335	import com.pousadamarealta.service.ReportService;
336	import io.javalin.Javalin;
337	
338	public class App {
339	    public static void main(String[] args) {
340	        int port = getPort();
341	
342	        ReservationRepository reservationRepo = new ReservationRepository();
343	        RoomRepository roomRepo = new RoomRepository();
344	        MessageRepository messageRepo = new MessageRepository();
345	        PricingService pricingService = new PricingService();
346	
347	        ReservationService reservationService = new ReservationService(
348	            reservationRepo,
349	            roomRepo,
350	            messageRepo,
351	            pricingService
352	        );
353	
354	        ReportService reportService = new ReportService(reservationRepo, roomRepo);
355	
356	        Javalin app = Javalin.create().start(port);
357	
358	        ReservationApi api = new ReservationApi(
359	            app,
360	            reservationService,
361	            reportService,
362	            roomRepo,
363	            messageRepo
364	        );
365	        api.setup();
366	
367	        System.out.println("Servidor rodando na porta " + port);
368	    }
369	
370	    private static int getPort() {
371	        String portEnv = System.getenv("PORT");
372	        if (portEnv != null && !portEnv.isEmpty()) {
373	            try {
374	                return Integer.parseInt(portEnv);
375	            } catch (NumberFormatException e) {
376	                return 7070;
377	            }
378	        }
379	        return 7070;
380	    }
381	}

