320	    private String formatDateRange(LocalDate checkIn, LocalDate checkOut) {
321	        return String.format("%s a %s",
322	            checkIn.format(DATE_FORMATTER),
323	            checkOut.format(DATE_FORMATTER)
324	        );
325	    }
