108	
109	public class ReservationApi {
110	    private final Javalin app;
111	    private final ReservationService reservationService;
112	    private final ReportService reportService;
113	    private final RoomRepository roomRepository;
114	    private final MessageRepository messageRepository;
115	
116	    public ReservationApi(
117	        Javalin app,
118	        ReservationService reservationService,
119	        ReportService reportService,
120	        RoomRepository roomRepository,
121	        MessageRepository messageRepository
122	    ) {
123	        this.app = app;
124	        this.reservationService = reservationService;
125	        this.reportService = reportService;
126	        this.roomRepository = roomRepository;
127	        this.messageRepository = messageRepository;
128	    }
129	
130	    public void setup() {
131	        app.get("/rooms", this::getRooms);
132	        app.post("/reservations", this::createReservation);
133	        app.get("/reservations/{id}", this::getReservation);
134	        app.post("/reservations/{id}/confirmation", this::confirmReservation);
135	        app.post("/reservations/{id}/cancellation", this::cancelReservation);
136	        app.post("/reservations/{id}/check-in", this::checkIn);
137	        app.post("/reservations/{id}/check-out", this::checkOut);
138	        app.get("/reservations/{id}/document", this::getDocument);
139	        app.get("/messages", this::getMessages);
140	        app.get("/reports/occupancy", this::getOccupancyReport);
141	        app.get("/reports/revenue", this::getRevenueReport);
142	    }
143	
144	    private void getRooms(Context ctx) {
145	        ctx.json(roomRepository.findAll().stream().map(RoomResponse::from).toList());
146	    }
147	
148	    private void createReservation(Context ctx) {
149	        try {
150	            ReservationRequest req = ctx.bodyAsClass(ReservationRequest.class);
151	            validateReservationRequest(req);
152	
153	            LocalDate checkIn = LocalDate.parse(req.checkIn());
154	            LocalDate checkOut = LocalDate.parse(req.checkOut());
155	            RatePlan ratePlan = RatePlan.valueOf(req.ratePlan());
156	
157	            Reservation reservation = reservationService.createReservation(
158	                req.roomNumber(),
159	                req.guestName(),
160	                req.guestEmail(),
161	                req.guestCpf(),
162	                checkIn,
163	                checkOut,
164	                req.guests(),
165	                ratePlan
166	            );
167	
168	            ctx.status(201).json(ReservationResponse.from(reservation));
169	        } catch (IllegalArgumentException e) {
170	            handleError(ctx, e.getMessage());
171	        } catch (DateTimeParseException e) {
172	            error(ctx, 400, "INVALID_REQUEST", "Invalid date format");
173	        } catch (IllegalStateException e) {
174	            error(ctx, 400, "INVALID_REQUEST", "Invalid request format");
175	        } catch (Exception e) {
176	            error(ctx, 400, "INVALID_REQUEST", "Invalid request");
177	        }
178	    }
179	
180	    private void getReservation(Context ctx) {
181	        try {
182	            long id = Long.parseLong(ctx.pathParam("id"));
183	            Reservation reservation = reservationService.getReservation(id);
184	            ctx.json(ReservationResponse.from(reservation));
185	        } catch (IllegalArgumentException e) {
186	            handleError(ctx, e.getMessage());
187	        }
188	    }
189	
190	    private void confirmReservation(Context ctx) {
191	        try {
192	            long id = Long.parseLong(ctx.pathParam("id"));
193	            Reservation reservation = reservationService.confirmReservation(id);
194	            ctx.json(ReservationResponse.from(reservation));
195	        } catch (IllegalArgumentException e) {
196	            handleError(ctx, e.getMessage());
197	        }
198	    }
199	
200	    private void cancelReservation(Context ctx) {
201	        try {
202	            long id = Long.parseLong(ctx.pathParam("id"));
203	            Reservation reservation = reservationService.cancelReservation(id);
204	            ctx.json(ReservationResponse.from(reservation));
205	        } catch (IllegalArgumentException e) {
206	            handleError(ctx, e.getMessage());
207	        }
208	    }
209	
210	    private void checkIn(Context ctx) {
211	        try {
212	            long id = Long.parseLong(ctx.pathParam("id"));
213	            Reservation reservation = reservationService.checkIn(id);
214	            ctx.json(ReservationResponse.from(reservation));
215	        } catch (IllegalArgumentException e) {
216	            handleError(ctx, e.getMessage());
217	        }
218	    }
219	
220	    private void checkOut(Context ctx) {
221	        try {
222	            long id = Long.parseLong(ctx.pathParam("id"));
223	            Reservation reservation = reservationService.checkOut(id);
224	            ReservationDocument doc = reservationService.getReservationDocument(id);
225	            ctx.json(DocumentResponse.from(doc));
226	        } catch (IllegalArgumentException e) {
227	            handleError(ctx, e.getMessage());
228	        }
229	    }
230	
231	    private void getDocument(Context ctx) {
232	        try {
233	            long id = Long.parseLong(ctx.pathParam("id"));
234	            ReservationDocument doc = reservationService.getReservationDocument(id);
235	            ctx.json(DocumentResponse.from(doc));
236	        } catch (IllegalArgumentException e) {
237	            handleError(ctx, e.getMessage());
238	        }
239	    }
240	
241	    private void getMessages(Context ctx) {
242	        ctx.json(messageRepository.findAll().stream().map(MessageResponse::from).toList());
243	    }
244	
245	    private void getOccupancyReport(Context ctx) {
246	        try {
247	            String dateStr = ctx.queryParam("date");
248	            if (dateStr == null) {
249	                error(ctx, 400, "INVALID_REQUEST", "date parameter is required");
250	                return;
251	            }
252	            LocalDate date = LocalDate.parse(dateStr);
253	            String report = reportService.generateOccupancyReport(date);
254	            ctx.contentType("text/csv; charset=utf-8").result(report);
255	        } catch (DateTimeParseException e) {
256	            error(ctx, 400, "INVALID_REQUEST", "Invalid date format");
257	        }
258	    }
259	
260	    private void getRevenueReport(Context ctx) {
261	        try {
262	            String monthStr = ctx.queryParam("month");
263	            if (monthStr == null) {
264	                error(ctx, 400, "INVALID_REQUEST", "month parameter is required");
265	                return;
266	            }
267	            YearMonth month = YearMonth.parse(monthStr);
268	            String report = reportService.generateRevenueReport(month);
269	            ctx.contentType("text/csv; charset=utf-8").result(report);
270	        } catch (DateTimeParseException e) {
271	            error(ctx, 400, "INVALID_REQUEST", "Invalid month format");
272	        }
273	    }
274	
275	    private void validateReservationRequest(ReservationRequest req) {
276	        if (req.roomNumber() <= 0 || req.guestName() == null || req.guestEmail() == null ||
277	            req.guestCpf() == null || req.checkIn() == null || req.checkOut() == null ||
278	            req.guests() < 1 || req.ratePlan() == null) {
279	            throw new IllegalArgumentException("INVALID_REQUEST");
280	        }
281	    }
282	
283	    private void handleError(Context ctx, String errorCode) {
284	        int status = switch (errorCode) {
285	            case "ROOM_NOT_FOUND" -> 404;
286	            case "RESERVATION_NOT_FOUND" -> 404;
287	            case "ROOM_UNAVAILABLE" -> 409;
288	            case "OPERATION_NOT_ALLOWED" -> 409;
289	            case "CAPACITY_EXCEEDED" -> 422;
290	            default -> 400;
291	        };
292	
293	        String message = switch (errorCode) {
294	            case "ROOM_NOT_FOUND" -> "Room not found";
295	            case "RESERVATION_NOT_FOUND" -> "Reservation not found";
296	            case "ROOM_UNAVAILABLE" -> "Room is not available for the selected dates";
297	            case "OPERATION_NOT_ALLOWED" -> "This operation is not allowed for the current reservation status";
298	            case "CAPACITY_EXCEEDED" -> "Number of guests exceeds room capacity";
299	            case "INVALID_REQUEST" -> "Invalid request";
300	            default -> "An error occurred";
301	        };
302	
303	        error(ctx, status, errorCode, message);
304	    }
305	
306	    private void error(Context ctx, int status, String errorCode, String message) {
307	        ctx.status(status).json(new ErrorResponse(errorCode, message));
308	    }
309	}
