312	import java.math.BigDecimal;
313	import java.math.RoundingMode;
314	import java.time.LocalDate;
315	
316	public class PricingService {
317	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
318	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
319	
320	    public boolean isHighSeason(LocalDate date) {
321	        int month = date.getMonthValue();
322	        int day = date.getDayOfMonth();
323	
324	        if (month >= 12 || month <= 2) {
325	            if (month == 2) return true;
326	            if (month == 12) return true;
327	            if (month == 1) return true;
328	            return false;
329	        }
330	
331	        if (month == 7) return true;
332	
333	        return false;
334	    }
335	
336	    public BigDecimal calculateNightlyRate(BigDecimal baseNightly, LocalDate date) {
337	        BigDecimal rate = baseNightly;
338	        if (isHighSeason(date)) {
339	            rate = rate.multiply(HIGH_SEASON_MULTIPLIER);
340	        }
341	        return round(rate);
342	    }
343	
344	    public BigDecimal calculateSubtotal(BigDecimal baseNightly, LocalDate checkIn, LocalDate checkOut) {
345	        BigDecimal subtotal = BigDecimal.ZERO;
346	        LocalDate current = checkIn;
347	        while (current.isBefore(checkOut)) {
348	            subtotal = subtotal.add(calculateNightlyRate(baseNightly, current));
349	            current = current.plusDays(1);
350	        }
351	        return subtotal;
352	    }
353	
354	    public BigDecimal calculateDiscount(BigDecimal subtotal, boolean isNonRefundable) {
355	        if (!isNonRefundable) {
356	            return BigDecimal.ZERO;
357	        }
358	        return round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
359	    }
360	
361	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
362	        return round(subtotal.subtract(discount));
363	    }
364	
365	    public int countNights(LocalDate checkIn, LocalDate checkOut) {
366	        return (int) checkIn.until(checkOut, java.time.temporal.ChronoUnit.DAYS);
367	    }
368	
369	    public static BigDecimal round(BigDecimal value) {
370	        return value.setScale(2, RoundingMode.HALF_EVEN);
371	    }
372	}
