385	public class ReportService {
386	    private final ReservationRepository reservationRepo;
387	    private final RoomRepository roomRepo;
388	
389	    public ReportService(ReservationRepository reservationRepo, RoomRepository roomRepo) {
390	        this.reservationRepo = reservationRepo;
391	        this.roomRepo = roomRepo;
392	    }
393	
394	    public String generateOccupancyReport(LocalDate date) {
395	        List<Reservation> reservations = reservationRepo.findAll().stream()
396	            .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
397	            .filter(r -> r.getStatus() == ReservationStatus.CONFIRMED ||
398	                        r.getStatus() == ReservationStatus.CHECKED_IN ||
399	                        r.getStatus() == ReservationStatus.CHECKED_OUT)
400	            .filter(r -> isOccupiedOnDate(r, date))
401	            .sorted(Comparator.comparingInt(Reservation::getRoomNumber))
402	            .toList();
403	
404	        StringBuilder csv = new StringBuilder();
405	        csv.append("room,type,reservation,check_in,check_out\n");
406	
407	        for (Reservation r : reservations) {
408	            String roomType = roomRepo.findByNumber(r.getRoomNumber())
409	                .map(room -> room.type().displayName)
410	                .orElse("UNKNOWN");
411	
412	            csv.append(r.getRoomNumber()).append(",")
413	                .append(roomType).append(",")
414	                .append(r.getId()).append(",")
415	                .append(formatDateCsv(r.getCheckIn())).append(",")
416	                .append(formatDateCsv(r.getCheckOut())).append("\n");
417	        }
418	
419	        int totalOccupied = reservations.size();
420	        int totalRooms = 5;
421	        csv.append("total,").append(totalOccupied).append("/").append(totalRooms);
422	
423	        return csv.toString();
424	    }
425	
426	    public String generateRevenueReport(YearMonth month) {
427	        List<Reservation> reservations = reservationRepo.findAll().stream()
428	            .filter(r -> {
429	                YearMonth resMonth = YearMonth.from(r.getCheckIn());
430	                return resMonth.equals(month);
431	            })
432	            .filter(r -> r.getAmountPaid().compareTo(BigDecimal.ZERO) > 0)
433	            .sorted(Comparator
434	                .comparing(Reservation::getCheckIn)
435	                .thenComparingLong(Reservation::getId))
436	            .toList();
437	
438	        StringBuilder csv = new StringBuilder();
439	        csv.append("reservation,room,check_in,check_out,status,amount\n");
440	
441	        BigDecimal total = BigDecimal.ZERO;
442	        for (Reservation r : reservations) {
443	            BigDecimal amount = r.getAmountPaid();
444	            if (r.getRefund() != null) {
445	                amount = amount.subtract(r.getRefund());
446	            }
447	
448	            csv.append(r.getId()).append(",")
449	                .append(r.getRoomNumber()).append(",")
450	                .append(formatDateCsv(r.getCheckIn())).append(",")
451	                .append(formatDateCsv(r.getCheckOut())).append(",")
452	                .append(r.getStatus().name()).append(",")
453	                .append(String.format("%.2f", amount)).append("\n");
454	
455	            total = total.add(amount);
456	        }
457	
458	        csv.append("total,,,,").append(String.format("%.2f", total));
459	
460	        return csv.toString();
461	    }
462	
463	    private boolean isOccupiedOnDate(Reservation r, LocalDate date) {
464	        return !date.isBefore(r.getCheckIn()) && date.isBefore(r.getCheckOut());
465	    }
466	
467	    private String formatDateCsv(LocalDate date) {
468	        return date.toString();
469	    }
470	}
